:root {
  --color-bg: #2d1b2e;
  --color-card: #fdf6f0;
  --color-primary: #e07a5f;
  --color-secondary: #3d405b;
  --color-accent: #81b29a;
  --color-text: #2d1b2e;
  --font-base: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: var(--font-base);
  line-height: 1.5;
  padding: 1rem;
}

.card {
  background: var(--color-card);
  border-radius: 1.25rem;
  padding: 2rem 1.5rem;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
}

h1 {
  font-size: 1.75rem;
  color: var(--color-secondary);
  text-align: center;
  margin-bottom: 0.25rem;
}

.subtitle {
  text-align: center;
  color: var(--color-secondary);
  opacity: 0.75;
  margin-bottom: 1.5rem;
  font-size: 1rem;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1.5rem;
}

label {
  font-weight: 600;
  color: var(--color-secondary);
}

input[type="number"] {
  font-size: 1rem;
  padding: 0.6rem 0.75rem;
  border: 2px solid var(--color-secondary);
  border-radius: 0.5rem;
  background: #fff;
  color: var(--color-text);
  transition: border-color 0.15s, box-shadow 0.15s;
  width: 100%;
}

input[type="number"]:hover {
  border-color: var(--color-primary);
}

input[type="number"]:focus-visible {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(224, 122, 95, 0.35);
}

input[type="number"]:active {
  border-color: var(--color-primary);
}

small {
  font-size: 0.875rem;
  color: var(--color-secondary);
  opacity: 0.7;
}

.ingredient-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.ingredient-list li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 0.65rem 0.85rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: 0.5rem;
  font-size: 1rem;
  font-weight: 500;
}

.ingredient-list .amount {
  font-weight: 700;
  white-space: nowrap;
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .ingredient-list li {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.2rem;
  }
}

// Built-in recipe: amounts for 4 servings
const BASE_SERVINGS = 4;
const recipe = [
  { name: 'Flour', amount: 200, unit: 'g' },
  { name: 'Sugar', amount: 100, unit: 'g' },
  { name: 'Butter', amount: 80, unit: 'g' },
  { name: 'Eggs', amount: 2, unit: '' },
  { name: 'Milk', amount: 120, unit: 'ml' }
];

const servingsInput = document.getElementById('servings');
const list = document.getElementById('ingredient-list');

function roundToOneDecimal(value) {
  return Math.round(value * 10) / 10;
}

function render(servings) {
  const factor = servings / BASE_SERVINGS;
  list.innerHTML = '';
  recipe.forEach(item => {
    const scaled = roundToOneDecimal(item.amount * factor);
    const li = document.createElement('li');
    li.innerHTML = `<span class="name">${item.name}</span><span class="amount">${scaled}${item.unit ? ' ' + item.unit : ''}</span>`;
    list.appendChild(li);
  });
}

function handleInput() {
  let value = parseInt(servingsInput.value, 10);
  if (isNaN(value)) {
    value = 1;
  }
  value = Math.min(12, Math.max(1, value));
  // Only update the input if the value changed to avoid cursor jumps
  if (servingsInput.value !== String(value)) {
    servingsInput.value = value;
  }
  render(value);
}

servingsInput.addEventListener('input', handleInput);
servingsInput.addEventListener('change', handleInput);

// Initial render
render(BASE_SERVINGS);
